function cx(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}

function demoAction(label: string) {
  window.dispatchEvent(new CustomEvent("demo-toast", { detail: `${label} is ready in demo mode.` }));
}

function statusClass(status: string) {
  if (status === "Review" || status === "Needs review") return "text-primary";
  if (status === "At risk") return "text-amber-700 dark:text-amber-300";
  if (status === "Done" || status === "On track") return "text-emerald-700 dark:text-emerald-300";
  return "text-foreground";
}

function StatusDot({ status }: { status: string }) {
  return <span className={cx("inline-flex items-center gap-2 text-xs font-medium", statusClass(status))}><span className={cx("h-2 w-2 rounded-full", status === "Planned" ? "border border-foreground/50" : status === "At risk" ? "bg-amber-500" : status === "Review" ? "bg-primary" : status === "Done" ? "bg-emerald-600" : "bg-foreground")} />{status}</span>;
}

function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) {
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/35 p-4" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="w-full max-w-lg rounded-xl border border-foreground/20 bg-card p-6 shadow-2xl"><div className="mb-5 flex items-start justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-muted-foreground">Workspace action</p><h2 className="mt-1 text-xl font-semibold tracking-[-0.04em]">{title}</h2></div><button onClick={onClose} className="rounded-md p-1.5 text-muted-foreground hover:bg-muted" aria-label="Close"><X className="h-4 w-4" /></button></div>{children}</div></div>;
}

function Button({ children, onClick, variant = "primary" }: { children: React.ReactNode; onClick?: () => void; variant?: "primary" | "outline" | "quiet" }) {
  const fallbackLabel = typeof children === "string" ? children : "This action";
  return <button onClick={onClick ?? (() => demoAction(fallbackLabel))} className={cx("inline-flex items-center justify-center gap-2 rounded-md px-3.5 py-2 text-sm font-semibold transition-all", variant === "primary" && "border border-foreground bg-primary text-primary-foreground shadow-[3px_3px_0_0_rgba(0,0,0,0.9)] hover:-translate-y-0.5", variant === "outline" && "border border-border bg-card hover:bg-muted", variant === "quiet" && "text-muted-foreground hover:bg-muted hover:text-foreground")}>{children}</button>;
}

function PageHeader({ title, description, icon: Icon, onCreate, createLabel = "Create" }: { title: string; description: string; icon: LucideIcon; onCreate: () => void; createLabel?: string }) {
  return <div className="mb-7 flex flex-wrap items-end justify-between gap-4"><div className="flex items-start gap-3"><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border border-foreground/20 bg-primary text-primary-foreground"><Icon className="h-4 w-4" /></div><div><h1 className="text-[1.75rem] font-semibold tracking-[-0.05em]">{title}</h1><p className="mt-1 max-w-2xl text-sm leading-relaxed text-muted-foreground">{description}</p></div></div><Button onClick={onCreate}><Plus className="h-4 w-4" />{createLabel}</Button></div>;
}

function DataTable({ records, onSelect }: { records: DemoRecord[]; onSelect: (record: DemoRecord) => void }) {
  return <div className="overflow-x-auto rounded-lg border border-border bg-card"><table className="w-full min-w-[680px] text-sm"><thead><tr className="border-b border-border"><th className="px-5 py-3 text-left">Name</th><th className="px-4 py-3 text-left">Status</th><th className="px-4 py-3 text-left">Owner / context</th><th className="px-4 py-3 text-left">Value</th><th className="px-4 py-3 text-right"> </th></tr></thead><tbody>{records.map((record) => <tr key={record.name} className="border-b border-border last:border-0"><td className="px-5 py-4"><button onClick={() => onSelect(record)} className="text-left font-semibold hover:text-primary">{record.name}</button><p className="mt-1 text-xs text-muted-foreground">{record.meta}</p></td><td className="px-4 py-4"><StatusDot status={record.status} /></td><td className="px-4 py-4 text-xs text-muted-foreground">{record.accent ?? "Operations"}</td><td className="px-4 py-4 text-xs font-medium">{record.value ?? "—"}</td><td className="px-4 py-4 text-right"><button onClick={() => onSelect(record)} className="rounded-md p-1 text-muted-foreground hover:bg-muted hover:text-foreground" aria-label={`Open ${record.name}`}><MoreHorizontal className="h-4 w-4" /></button></td></tr>)}</tbody></table></div>;
}

