function UtilityPage({ title, description, icon: Icon, openCreate, navigate, route }: { title: string; description: string; icon: LucideIcon; openCreate: () => void; navigate: (path: string) => void; route: string }) {
  const records: DemoRecord[] = useMemo(() => {
    const stems = route.includes("stakeholder") ? ["Ministry steering group", "Creative leadership", "Client success team", "Executive sponsor"] : route.includes("risk") ? ["Timeline compression", "Review dependency", "Capacity gap", "Scope drift"] : route.includes("document") ? ["Delivery playbook", "Project brief", "Decision log", "Retrospective notes"] : ["Launch readiness review", "Workspace navigation", "Client onboarding", "Quarterly planning"];
    return stems.map((name, index) => ({ name, meta: index % 2 ? "Updated yesterday" : "Updated today", status: index === 1 ? "Review" : index === 2 ? "In progress" : "On track", accent: index % 2 ? "Cross-functional" : "Operations", value: index === 0 ? "High" : `${index + 2} items` }));
  }, [route]);
  return <><PageHeader title={title} description={description} icon={Icon} onCreate={openCreate} createLabel="New item" /><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2 rounded-md border border-border bg-card px-3 py-2 text-xs text-muted-foreground"><Search className="h-3.5 w-3.5" />Search {title.toLowerCase()}</div><div className="flex gap-2"><Button variant="outline">All statuses <ChevronDown className="h-3.5 w-3.5" /></Button><Button variant="quiet">Saved view</Button></div></div><DataTable records={records} onSelect={(record) => navigate(`${route}/${encodeURIComponent(record.name.toLowerCase().replaceAll(" ", "-"))}`)} /><div className="mt-5 rounded-lg border border-dashed border-border bg-card/40 p-8 text-center"><p className="text-sm font-semibold">Everything in one place</p><p className="mt-1 text-xs text-muted-foreground">Create, filter, review, and open any record to continue the flow.</p></div></>;
}

function titleFromSlug(slug: string) {
  return decodeURIComponent(slug).split("-").map((word) => word ? word[0].toUpperCase() + word.slice(1) : word).join(" ");
}

function UtilityDetailPage({ route, navigate, openCreate }: { route: string; navigate: (path: string) => void; openCreate: () => void }) {
  const slug = route.split("/").filter(Boolean).pop() ?? "record";
  const title = titleFromSlug(slug);
  return <><button onClick={() => navigate(route.split("/").slice(0, -1).join("/") || "/")} className="mb-5 inline-flex items-center gap-1 text-xs font-semibold text-muted-foreground hover:text-foreground"><ChevronLeft className="h-3.5 w-3.5" />Back to list</button><div className="mb-7 flex flex-wrap items-start justify-between gap-4"><div><div className="mb-3 flex items-center gap-2"><StatusDot status="On track" /><span className="text-xs text-muted-foreground">Updated today</span></div><h1 className="text-[1.9rem] font-semibold tracking-[-0.05em]">{title}</h1><p className="mt-1 text-sm text-muted-foreground">Workspace record · Operations</p></div><div className="flex gap-2"><Button variant="outline" onClick={() => demoAction("Record archived")}>Archive</Button><Button onClick={openCreate}><Plus className="h-4 w-4" />Add follow-up</Button></div></div><div className="grid gap-5 lg:grid-cols-[1.35fr_0.65fr]"><div className="space-y-5"><div className="rounded-lg border border-border bg-card p-5"><h2 className="font-semibold">Overview</h2><p className="mt-3 text-sm leading-relaxed text-muted-foreground">This demo record is connected to the shared workspace flow. Use the actions above to move it forward, add a follow-up, or return to the list.</p><div className="mt-5 grid gap-4 sm:grid-cols-3">{[["Owner", "Sara Tarek Ammar"], ["Priority", "High"], ["Due date", "Aug 28"]].map(([label, value]) => <div key={label} className="rounded-md border border-border bg-background p-3"><p className="text-[10px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">{label}</p><p className="mt-2 text-sm font-semibold">{value}</p></div>)}</div></div><div className="rounded-lg border border-border bg-card p-5"><div className="flex items-center justify-between"><h2 className="font-semibold">Activity</h2><Button variant="quiet" onClick={() => demoAction("Comment composer")}>Add note</Button></div><div className="mt-4 space-y-4 border-s border-border ps-4"><div><p className="text-sm font-medium">Sara moved this record to On track</p><p className="mt-1 text-xs text-muted-foreground">Today at 09:42</p></div><div><p className="text-sm font-medium">Nour added a delivery note</p><p className="mt-1 text-xs text-muted-foreground">Yesterday at 16:18</p></div></div></div></div><div className="space-y-5"><div className="rounded-lg border border-border bg-card p-5"><p className="text-xs font-semibold uppercase tracking-[0.12em] text-muted-foreground">Progress</p><p className="mt-3 text-2xl font-semibold">68%</p><div className="mt-4 h-2 rounded-full bg-muted"><div className="h-full w-[68%] rounded-full bg-primary" /></div><p className="mt-2 text-xs text-muted-foreground">4 of 6 milestones complete</p></div><div className="rounded-lg border border-border bg-card p-5"><p className="text-xs font-semibold uppercase tracking-[0.12em] text-muted-foreground">Next step</p><p className="mt-3 text-sm font-semibold">Review readiness checklist</p><button onClick={() => demoAction("Checklist opened")} className="mt-3 text-xs font-semibold text-primary">Open checklist →</button></div></div></div></>;
}

