function StakeholderDetailDemoPage({ navigate, openCreate }: { navigate: (path: string) => void; openCreate: () => void }) {
  return <><button onClick={() => navigate("/stakeholders")} className="mb-5 inline-flex items-center gap-1 text-xs font-semibold text-muted-foreground hover:text-foreground"><ChevronLeft className="h-3.5 w-3.5" />Back to stakeholders</button><div className="mb-7 flex flex-wrap items-start justify-between gap-4"><div><p className="mb-2 text-[10px] font-bold uppercase tracking-[0.16em] text-muted-foreground">Stakeholder profile</p><h1 className="text-[1.9rem] font-semibold tracking-[-0.05em]">Executive sponsor</h1><div className="mt-3 flex flex-wrap items-center gap-3"><StatusDot status="On track" /><span className="text-xs text-muted-foreground">High influence · Northstar Media</span></div></div><div className="flex gap-2"><Button variant="outline" onClick={() => demoAction("Engagement logged")}>Log engagement</Button><Button onClick={openCreate}><Plus className="h-4 w-4" />Schedule touchpoint</Button></div></div><div className="grid gap-5 lg:grid-cols-[1.2fr_0.8fr]"><div className="space-y-5"><div className="rounded-lg border border-border bg-card p-5"><h2 className="font-semibold">Relationship summary</h2><p className="mt-3 text-sm leading-relaxed text-muted-foreground">A high-influence stakeholder who is engaged with the delivery plan and expects a concise weekly view of progress, risks, and decisions.</p><div className="mt-5 grid gap-4 sm:grid-cols-3">{[["Influence", "High"], ["Sentiment", "Positive"], ["Last touchpoint", "Aug 14"]].map(([label, value]) => <div key={label} className="rounded-md border border-border bg-background p-3"><p className="text-[10px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">{label}</p><p className="mt-2 text-sm font-semibold">{value}</p></div>)}</div></div><div className="rounded-lg border border-border bg-card p-5"><div className="flex items-center justify-between"><h2 className="font-semibold">Recent engagement</h2><Button variant="quiet" onClick={() => demoAction("Engagement history opened")}>View all</Button></div><div className="mt-4 space-y-4 border-s border-border ps-4"><div><p className="text-sm font-medium">Received the weekly delivery brief</p><p className="mt-1 text-xs text-muted-foreground">Aug 14 · Positive response</p></div><div><p className="text-sm font-medium">Joined launch readiness review</p><p className="mt-1 text-xs text-muted-foreground">Aug 12 · Decision made</p></div></div></div></div><div className="space-y-5"><div className="rounded-lg border border-border bg-card p-5"><p className="text-xs font-semibold uppercase tracking-[0.12em] text-muted-foreground">Next touchpoint</p><p className="mt-3 text-sm font-semibold">Steering group check-in</p><p className="mt-1 text-xs text-muted-foreground">Thursday, Aug 20 · 10:00</p><button onClick={openCreate} className="mt-4 text-xs font-semibold text-primary">Open agenda →</button></div><div className="rounded-lg border border-border bg-card p-5"><p className="text-xs font-semibold uppercase tracking-[0.12em] text-muted-foreground">Linked work</p><div className="mt-4 space-y-3">{["Operation Hub", "Launch Campaign", "Q3 delivery report"].map((item) => <button key={item} onClick={() => demoAction(`${item} opened`)} className="flex w-full items-center justify-between text-left text-sm font-medium hover:text-primary"><span>{item}</span><ArrowRight className="h-3.5 w-3.5" /></button>)}</div></div></div></div></>;
}

function ProjectCreatePage({ navigate }: { navigate: (path: string) => void }) {
  const [created, setCreated] = useState(false);
  return <><button onClick={() => navigate("/projects")} className="mb-5 inline-flex items-center gap-1 text-xs font-semibold text-muted-foreground hover:text-foreground"><ChevronLeft className="h-3.5 w-3.5" />Back to projects</button><div className="mb-7"><p className="mb-1 text-[10px] font-bold uppercase tracking-[0.16em] text-muted-foreground">Project intake</p><h1 className="text-[1.9rem] font-semibold tracking-[-0.05em]">Create a project</h1><p className="mt-1 text-sm text-muted-foreground">Start with enough context for the team to move confidently.</p></div><div className="grid gap-5 lg:grid-cols-[1.2fr_0.8fr]"><div className="rounded-lg border border-border bg-card p-5"><div className="grid gap-5 sm:grid-cols-2"><label className="text-xs font-semibold sm:col-span-2">Project name<input placeholder="e.g. Client onboarding" className="mt-2 w-full rounded-md border border-border bg-background px-3 py-2 text-sm font-normal outline-none focus:border-primary" /></label><label className="text-xs font-semibold">Owner<select defaultValue="Sara" className="mt-2 w-full rounded-md border border-border bg-background px-3 py-2 text-sm font-normal outline-none"><option>Sara</option><option>Nour</option><option>Omar</option></select></label><label className="text-xs font-semibold">Target date<input type="date" defaultValue="2026-09-04" className="mt-2 w-full rounded-md border border-border bg-background px-3 py-2 text-sm font-normal outline-none" /></label><label className="text-xs font-semibold sm:col-span-2">Outcome<textarea placeholder="What should be true when this project is complete?" className="mt-2 min-h-28 w-full rounded-md border border-border bg-background px-3 py-2 text-sm font-normal outline-none focus:border-primary" /></label></div><div className="mt-6 flex justify-end gap-2"><Button variant="outline" onClick={() => navigate("/projects")}>Cancel</Button><Button onClick={() => setCreated(true)}>{created ? "Project created" : "Create project"}</Button></div></div><div className="space-y-5"><div className="rounded-lg border border-border bg-card p-5"><p className="text-xs font-semibold uppercase tracking-[0.12em] text-muted-foreground">Suggested setup</p><div className="mt-4 space-y-3">{["Create default board", "Add launch milestone", "Invite project team", "Start first sprint"].map((item, index) => <label key={item} className="flex items-center gap-3 text-sm"><input type="checkbox" defaultChecked={index < 2} className="h-4 w-4 accent-[var(--primary)]" />{item}</label>)}</div></div><div className="rounded-lg border border-primary/30 bg-primary/5 p-5"><p className="text-sm font-semibold">A good project starts with a clear outcome.</p><p className="mt-2 text-xs leading-relaxed text-muted-foreground">You can add the detailed plan, risks, and stakeholders after the project is created.</p></div></div></div></>;
}

function SpecializedPage({ spec, openCreate, navigate }: { spec: SpecializedSpec; openCreate: () => void; navigate: (path: string) => void }) {
  const [activeTab, setActiveTab] = useState("Overview");
  const tabs = spec.variant === "planning" ? ["Overview", "Timeline", "Dependencies", "Decisions"] : spec.variant === "presales" ? ["Pipeline", "Activity", "Segments", "Forecast"] : spec.variant === "insights" ? ["Overview", "Trends", "Breakdown", "Exports"] : spec.variant === "people" ? ["Directory", "Capacity", "Engagement", "Reviews"] : ["Overview", "Activity", "Rules", "History"];
  return <><div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div className="flex items-start gap-3"><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border border-foreground/20 bg-primary text-primary-foreground"><spec.icon className="h-4 w-4" /></div><div><p className="mb-1 text-[10px] font-bold uppercase tracking-[0.16em] text-muted-foreground">{spec.eyebrow}</p><h1 className="text-[1.8rem] font-semibold tracking-[-0.05em]">{spec.label}</h1><p className="mt-1 max-w-2xl text-sm leading-relaxed text-muted-foreground">{spec.description}</p></div></div><div className="flex gap-2"><Button variant="outline" onClick={() => demoAction(`${spec.secondary} opened`)}>{spec.secondary}</Button><Button onClick={openCreate}><Plus className="h-4 w-4" />{spec.primary}</Button></div></div><div className="mb-6 flex flex-wrap gap-1 border-b border-border">{tabs.map((tab) => <button key={tab} onClick={() => { setActiveTab(tab); demoAction(`${tab} view selected`); }} className={cx("border-b-2 px-4 py-3 text-sm font-semibold", activeTab === tab ? "border-primary text-foreground" : "border-transparent text-muted-foreground hover:text-foreground")}>{tab}</button>)}</div><section className="grid gap-4 sm:grid-cols-3">{spec.stats.map(([label, value, meta]) => <div key={label} className="rounded-lg border border-border bg-card p-5"><p className="text-xs font-semibold uppercase tracking-[0.12em] text-muted-foreground">{label}</p><div className="mt-4 flex items-end justify-between gap-3"><p className="text-3xl font-semibold tracking-[-0.06em]">{value}</p><span className="text-xs font-semibold text-primary">{meta}</span></div></div>)}</section><div className="mt-5 grid gap-5 xl:grid-cols-[1.25fr_0.75fr]"><div className="rounded-lg border border-border bg-card p-5"><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-semibold">{activeTab === "Overview" ? "Current work" : activeTab}</h2><p className="mt-1 text-xs text-muted-foreground">{spec.label} records and their next operational move.</p></div><div className="flex items-center gap-2 rounded-md border border-border bg-background px-3 py-2 text-xs text-muted-foreground"><Search className="h-3.5 w-3.5" />Filter view</div></div><div className="overflow-x-auto"><table className="w-full min-w-[620px] text-sm"><thead><tr className="border-b border-border"><th className="px-2 py-3 text-left">Item</th><th className="px-3 py-3 text-left">Status</th><th className="px-3 py-3 text-left">Owner / context</th><th className="px-3 py-3 text-right">Value</th></tr></thead><tbody>{spec.records.map(([name, status, context, value]) => <tr key={name} className="border-b border-border last:border-0"><td className="px-2 py-4"><button onClick={() => navigate(`${window.location.pathname}/${name.toLowerCase().replaceAll(" ", "-")}`)} className="text-left font-semibold hover:text-primary">{name}</button><p className="mt-1 text-xs text-muted-foreground">Updated today</p></td><td className="px-3 py-4"><StatusDot status={status === "Needs follow-up" || status === "At risk" || status === "Blocked" ? "At risk" : status === "New" || status === "Draft" ? "Review" : "On track"} /></td><td className="px-3 py-4 text-xs text-muted-foreground">{context}</td><td className="px-3 py-4 text-right text-xs font-semibold">{value}</td></tr>)}</tbody></table></div></div><div className="space-y-5"><div className="rounded-lg border border-border bg-card p-5"><div className="flex items-center justify-between"><div><h2 className="font-semibold">Signal snapshot</h2><p className="mt-1 text-xs text-muted-foreground">Last 7 days</p></div><LineChart className="h-4 w-4 text-primary" /></div><div className="mt-7 flex h-28 items-end gap-2 border-b border-border">{[38, 54, 47, 71, 62, 82, 68, 88, 76, 92].map((height, index) => <div key={index} className={cx("flex-1 rounded-t-sm", index === 9 ? "bg-primary" : "bg-primary/20")} style={{ height: `${height}%` }} />)}</div><div className="mt-3 flex justify-between text-[10px] text-muted-foreground"><span>Mon</span><span>Sun</span></div></div><div className="rounded-lg border border-border bg-card p-5"><p className="text-xs font-semibold uppercase tracking-[0.12em] text-muted-foreground">Next best action</p><p className="mt-3 text-sm font-semibold">{spec.primary} for the highest-priority item</p><p className="mt-2 text-xs leading-relaxed text-muted-foreground">Keep momentum by resolving the item with the most influence on this {spec.label.toLowerCase()} view.</p><button onClick={openCreate} className="mt-4 text-xs font-semibold text-primary">Take action →</button></div></div></div></>;
}
